package com.example.familymenu.category.api;
import com.example.familymenu.category.domain.*; import com.example.familymenu.category.dto.*; import com.example.familymenu.category.service.*; import com.example.familymenu.common.api.ApiResponse; import javax.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/dish-categories") @RequiredArgsConstructor public class CategoryController {private final CategoryService service;@GetMapping public ApiResponse<List<DishCategory>> list(@RequestParam(defaultValue="false") boolean all){return ApiResponse.success(service.list(all));}@PostMapping public ApiResponse<DishCategory> create(@Valid @RequestBody CategoryRequest r){return ApiResponse.success(service.create(r.getName(),r.getSort(),r.getEnabled()));}@PutMapping("/{id}") public ApiResponse<DishCategory> update(@PathVariable Long id,@Valid @RequestBody CategoryRequest r){return ApiResponse.success(service.update(id,r.getName(),r.getSort(),r.getEnabled()));}@DeleteMapping("/{id}") public ApiResponse<Void> delete(@PathVariable Long id){service.delete(id);return ApiResponse.success(null);}}
